Here is the original GNU C++ code you have to translate:
<original_code>
#include <bits/stdc++.h>
using namespace std;

const int MAXN = 20;
const int MAXV = 2 * MAXN * MAXN;
const int INF = 0x3f3f3f3f;

char firstGrid[MAXN][MAXN], secondGrid[MAXN][MAXN];
int infectTime[MAXN][MAXN];
int N, timeLimit;
int dx[4] = {1,0,-1,0};
int dy[4] = {0,1,0,-1};

inline bool isZeroToNine(char c) { return c >= '0' && c <= '9'; }
inline bool isOneToNine(char c) { return c >= '1' && c <= '9'; }

struct Dinic {
    struct Edge {
        int to, rev, cap;
    };
    vector<Edge> g[MAXV];
    int level[MAXV];
    bool seen[MAXV];

    void addEdge(int u, int v, int c) {
        if (u == v) return;
        for (auto &e : g[u]) {
            if (e.to == v) {
                e.cap = c;
                g[v][e.rev].cap = 0;
                return;
            }
        }
        Edge a = {v, (int)g[v].size(), c};
        Edge b = {u, (int)g[u].size(), 0};
        g[u].push_back(a);
        g[v].push_back(b);
    }

    bool bfs(int s, int t) {
        memset(level, -1, sizeof(level));
        queue<int> q;
        level[s] = 0;
        q.push(s);
        while (!q.empty()) {
            int u = q.front(); q.pop();
            for (const auto &e : g[u]) {
                if (e.cap > 0 && level[e.to] == -1) {
                    level[e.to] = level[u] + 1;
                    q.push(e.to);
                }
            }
        }
        return level[t] != -1;
    }

    int dfs(int u, int t, int flow) {
        if (u == t) return flow;
        seen[u] = true;
        for (auto &e : g[u]) {
            if (e.cap > 0 && !seen[e.to] && level[e.to] == level[u] + 1) {
                int got = dfs(e.to, t, min(flow, e.cap));
                if (got > 0) {
                    e.cap -= got;
                    g[e.to][e.rev].cap += got;
                    return got;
                }
            }
        }
        return 0;
    }

    int maxFlow(int s, int t) {
        int flow = 0;
        while (bfs(s, t)) {
            memset(seen, 0, sizeof(seen));
            int got;
            while ((got = dfs(s, t, INF)) > 0) flow += got;
        }
        return flow;
    }
};

Dinic solver;

void zombieTraversal(int sx, int sy) {
    for (int i = 0; i < N; ++i)
        for (int j = 0; j < N; ++j)
            infectTime[i][j] = INF;
    infectTime[sx][sy] = 0;
    queue<pair<int,int>> q;
    q.push(make_pair(sx, sy));
    while (!q.empty()) {
        int x = q.front().first, y = q.front().second;
        q.pop();
        for (int k = 0; k < 4; ++k) {
            int nx = x + dx[k], ny = y + dy[k];
            if (nx < 0 || nx >= N || ny < 0 || ny >= N) continue;
            if (isZeroToNine(firstGrid[nx][ny]) && infectTime[nx][ny] == INF) {
                infectTime[nx][ny] = infectTime[x][y] + 1;
                q.push(make_pair(nx, ny));
            }
        }
    }
}

void addAllSourceEdges(int sx, int sy) {
    int dist[MAXN][MAXN];
    memset(dist, INF, sizeof(dist));
    dist[sx][sy] = 0;

    if (isOneToNine(secondGrid[sx][sy]))
        solver.addEdge(N * sx + sy, N * N + N * sx + sy, INF);

    queue<pair<int,int>> q;
    q.push(make_pair(sx, sy));
    while (!q.empty()) {
        int x = q.front().first, y = q.front().second;
        q.pop();
        for (int d = 0; d < 4; ++d) {
            int nx = x + dx[d], ny = y + dy[d];
            if (nx < 0 || nx >= N || ny < 0 || ny >= N) continue;
            if (dist[nx][ny] != INF) continue;
            if (!isZeroToNine(firstGrid[nx][ny])) continue;

            int nt = dist[x][y] + 1;
            if (nt <= min(infectTime[nx][ny] - 1, timeLimit)) {
                dist[nx][ny] = nt;
                q.push(make_pair(nx, ny));
            }
            if (nt <= min(infectTime[nx][ny], timeLimit) && isOneToNine(secondGrid[nx][ny]))
                solver.addEdge(N * sx + sy, N * N + N * nx + ny, INF);
        }
    }
}

int main() {
    scanf("%d%d", &N, &timeLimit);
    int zx = 0, zy = 0;
    for (int i = 0; i < N; ++i) {
        for (int j = 0; j < N; ++j) {
            scanf(" %c", &firstGrid[i][j]);
            if (firstGrid[i][j] == 'Z') {
                zx = i; zy = j;
            } else if (isOneToNine(firstGrid[i][j])) {
                solver.addEdge(MAXV - 2, i * N + j, firstGrid[i][j] - '0');
            }
        }
    }

    zombieTraversal(zx, zy);

    for (int i = 0; i < N; ++i) {
        for (int j = 0; j < N; ++j) {
            scanf(" %c", &secondGrid[i][j]);
            if (isOneToNine(secondGrid[i][j]))
                solver.addEdge(N * N + i * N + j, MAXV - 1, secondGrid[i][j] - '0');
        }
    }

    for (int i = 0; i < N; ++i)
        for (int j = 0; j < N; ++j)
            if (isOneToNine(firstGrid[i][j])) addAllSourceEdges(i, j);

    printf("%d\n", solver.maxFlow(MAXV - 2, MAXV - 1));
    return 0;
}
